SELECT close_date AS close_date , CASE WHEN status_cd IN ('1','5','2') THEN manage_date ELSE null END AS manage_date , class_nm AS class_name , title AS title , CASE WHEN length(contt) > 300 THEN SUBSTR(contt,1,300)||'...' ELSE contt END AS content_limit , deadline_nm AS deadline_name , f_cdnm('ScheduleStatusCode', status_cd, company_id, close_date) AS status_name , CASE WHEN status_cd IN ('1','5','2') THEN f_emp_kor_nm(person_id) ELSE null END AS person_name , note AS note , info_id AS real_info_id , ROW_NUMBER() OVER(ORDER BY close_date, seq, title COLLATE "ko_KR.utf8") AS info_id , class_id AS class_id , deadline_id AS deadline_id , contt AS content , manager_id AS manager_id , f_emp_kor_nm(manager_id) AS manager_name , person_id AS person_id , f_get_empTrans(manager_id, close_date, 'org_code_nm') AS org_name , company_id AS company_id FROM ( SELECT sch04_info_id AS info_id , sch04_company_id AS company_id , sch04_title AS title , sch01_content AS contt , sch04_note AS note , sch04_manager_id AS manager_id , sch04_person_id AS person_id , sch01_class_id AS class_id , sch08_class_nm AS class_nm , COALESCE(sch08_seq,999) AS seq , sch04_close_date AS close_date , sch04_deadline_id AS deadline_id , f_get_deadline_nm(sch04_deadline_id, '2') AS deadline_nm , sch03_cycle_cd AS cycle_cd , sch04_manage_date AS manage_date , sch04_status_cd AS status_cd FROM sch04_list INNER JOIN sch03_deadline ON sch03_deadline_id = sch04_deadline_id INNER JOIN sch01_info ON sch01_info_id = sch04_info_id LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id WHERE sch04_company_id = #{companyId} AND sch04_schedule_cd = '1' /*(1:스케줄)*/ AND sch04_close_date BETWEEN #{startDate}::date AND #{endDate}::date AND sch04_status_cd != '9'
AND sch01_class_id = #{classId}
AND ( ( #{dailyYn} = 'true' AND COALESCE(sch01_daily_yn,'false') = 'true' ) OR ( #{dailyYn} != 'true' ) ) AND ( ( sch04_manager_id != #{personId} AND COALESCE(sch01_private_yn,'false') != 'true' ) OR ( sch04_manager_id = #{personId} ) ) AND ( ( #{shareType} IN ('%','1') AND #{personId} IN (sch04_manager_id, sch04_person_id) ) OR ( #{shareType} IN ('%','2') AND #{personId} NOT IN (sch04_manager_id, sch04_person_id) AND ( ( #{personId} IN ( SELECT sch02_person_id FROM sch02_share WHERE sch02_info_id = sch01_info_id AND sch02_share_cd = '1' ) ) OR ( #{orgId} IN ( SELECT sch02_org_id FROM sch02_share WHERE sch02_info_id = sch01_info_id AND sch02_share_cd = '2' ) ) ) ) ) UNION ALL SELECT * , null manage_date , '0' status_cd FROM ( -------------------------- -- 나의 스케줄 -------------------------- SELECT sch01_info_id info_id , sch01_company_id company_id , sch01_title title , sch01_content contt , sch01_note note , sch01_manager_id manager_id , sch01_manager_id person_id , sch01_class_id class_id , sch08_class_nm class_nm , COALESCE(sch08_seq,999) seq , f_get_std_date(sch03_deadline_id, sys12_day::date, sch01_company_id) close_date , sch03_deadline_id deadline_id , f_get_deadline_nm(sch03_deadline_id, '2') deadline_nm , sch03_cycle_cd cycle_cd FROM sch01_info INNER JOIN sch03_deadline ON sch03_info_id = sch01_info_id LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id INNER JOIN sys12_calendar ON ( sys12_company_id = sch01_company_id AND sys12_day BETWEEN #{startDate}::timestamp AND #{endDate}::timestamp ) WHERE sch01_company_id = #{companyId} AND sch01_manager_id = #{personId}
AND sch01_class_id = #{classId}
AND ( ( #{dailyYn} = 'true' AND COALESCE(sch01_daily_yn,'false') = 'true' ) OR ( #{dailyYn} != 'true' ) ) AND #{shareType} IN ('1','%') AND COALESCE(sch01_use_yn,'false') = 'true' AND sch03_cycle_calc_type NOT IN ('02','10') /*(02:수시기간설정/10:즉시)제외*/ AND sch03_cycle_cd NOT IN ('02','03','04','05','06') /*(주/월/분기/반기/연)제외*/ UNION ALL SELECT sch01_info_id info_id , sch01_company_id company_id , sch01_title title , sch01_content contt , sch01_note note , sch01_manager_id manager_id , sch01_manager_id person_id , sch01_class_id class_id , sch08_class_nm class_nm , COALESCE(sch08_seq,999) seq , sch09_day close_date , sch03_deadline_id deadline_id , f_get_deadline_nm(sch03_deadline_id, '2') deadline_nm , sch03_cycle_cd cycle_cd FROM sch01_info INNER JOIN sch03_deadline ON sch03_info_id = sch01_info_id INNER JOIN sch09_deadline_day ON sch09_deadline_id = sch03_deadline_id LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id WHERE sch01_company_id = #{companyId} AND sch01_manager_id = #{personId}
AND sch01_class_id = #{classId}
AND ( ( #{dailyYn} = 'true' AND COALESCE(sch01_daily_yn,'false') = 'true' ) OR ( #{dailyYn} != 'true' ) ) AND #{shareType} IN ('1','%') AND COALESCE(sch01_use_yn,'false') = 'true' AND sch03_cycle_calc_type NOT IN ('02','10') /*(02:수시기간설정/10:즉시)제외*/ AND sch03_cycle_cd IN ('02','03','04','05','06') /*(주/월/분기/반기/연)*/ AND sch09_day BETWEEN #{startDate}::date AND #{endDate}::date -------------------------- -- 공유 스케줄 -------------------------- UNION SELECT sch01_info_id info_id , sch01_company_id company_id , sch01_title title , sch01_content contt , sch01_note note , sch01_manager_id manager_id , sch01_manager_id person_id , sch01_class_id class_id , sch08_class_nm class_nm , COALESCE(sch08_seq,999) seq , f_get_std_date(sch03_deadline_id, sys12_day::date, sch01_company_id) close_date , sch03_deadline_id deadline_id , f_get_deadline_nm(sch03_deadline_id, '2') deadline_nm , sch03_cycle_cd cycle_cd FROM sch01_info INNER JOIN sch03_deadline ON sch03_info_id = sch01_info_id LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id INNER JOIN sys12_calendar ON ( sys12_company_id = sch01_company_id AND sys12_day BETWEEN #{startDate}::timestamp AND #{endDate}::timestamp ) WHERE sch01_company_id = #{companyId} AND sch01_manager_id != #{personId} AND COALESCE(#{classId,jdbcType=BIGINT},1) = 1 AND 'false' = #{dailyYn} AND COALESCE(sch01_use_yn,'false') = 'true' AND COALESCE(sch01_private_yn,'false') != 'true' AND sch03_cycle_calc_type NOT IN ('02','10') /*(02:수시기간설정/10:즉시)제외 */ AND sch03_cycle_cd NOT IN ('02','03','04','05','06') /*(주/월/분기/반기/연)제외*/ AND #{shareType} IN ('2','%') AND ( ( #{personId} IN ( SELECT sch02_person_id FROM sch02_share WHERE sch02_info_id = sch01_info_id AND sch02_share_cd = '1' ) ) OR ( #{orgId} IN ( SELECT sch02_org_id FROM sch02_share WHERE sch02_info_id = sch01_info_id AND sch02_share_cd = '2' ) ) ) UNION ALL SELECT sch01_info_id info_id , sch01_company_id company_id , sch01_title title , sch01_content contt , sch01_note note , sch01_manager_id manager_id , sch01_manager_id person_id , sch01_class_id class_id , sch08_class_nm class_nm , COALESCE(sch08_seq,999) seq , sch09_day close_date , sch03_deadline_id deadline_id , f_get_deadline_nm(sch03_deadline_id, '2') deadline_nm , sch03_cycle_cd cycle_cd FROM sch01_info INNER JOIN sch03_deadline ON sch03_info_id = sch01_info_id INNER JOIN sch09_deadline_day ON sch09_deadline_id = sch03_deadline_id LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id WHERE sch01_company_id = #{companyId} AND sch01_manager_id != #{personId} AND COALESCE(#{classId,jdbcType=BIGINT},1) = 1 AND 'false' = #{dailyYn} AND COALESCE(sch01_use_yn,'false') = 'true' AND COALESCE(sch01_private_yn,'false') != 'true' AND sch03_cycle_calc_type NOT IN ('02','10') /*(02:수시기간설정/10:즉시)제외 */ AND sch03_cycle_cd IN ('02','03','04','05','06') /*(주/월/분기/반기/연)*/ AND sch09_day BETWEEN #{startDate}::date AND #{endDate}::date AND #{shareType} IN ('2','%') AND ( ( #{personId} IN ( SELECT sch02_person_id FROM sch02_share WHERE sch02_info_id = sch01_info_id AND sch02_share_cd = '1' ) ) OR ( #{orgId} IN ( SELECT sch02_org_id FROM sch02_share WHERE sch02_info_id = sch01_info_id AND sch02_share_cd = '2' ) ) ) -------------------------- -- 공모주 일정 -------------------------- UNION SELECT info_id info_id , #{companyId} company_id , title title , content contt , null note , null manager_id , null person_id , 0 class_id , '공모주' class_nm , 999 seq , close_date close_date , null deadline_id , '수시' deadline_nm , '99' cycle_cd FROM ( SELECT sch10_ipo_id as info_id , '[수요예측] '||sch10_item_nm as title , CONCAT('시장구분 : ', f_cdnm('MarketCode', sch10_market_cd, sch10_company_id, f_today()) ,' / ' ,'희망공모가 : ',sch10_price_bracket ,E'\n주간사 : ',sch10_note) as content , sch10_demand_start_date as close_date FROM sch10_ipo WHERE sch10_demand_start_date BETWEEN #{startDate}::date AND #{endDate}::date AND COALESCE(sch10_cancel_yn,'false') != 'true' UNION ALL SELECT sch10_ipo_id as info_id , '[공모주청약] '||sch10_item_nm as title , CONCAT('시장구분 : ',f_cdnm('MarketCode', sch10_market_cd, sch10_company_id, f_today()) ,' / ' ,'공모가 : ',COALESCE(TO_CHAR(sch10_price,'FM999,999,999'),'미정') ,E'\n주간사 : ',sch10_note) as content , sch10_subscription_start_date as close_date FROM sch10_ipo WHERE sch10_subscription_start_date BETWEEN #{startDate}::date AND #{endDate}::date AND COALESCE(sch10_cancel_yn,'false') != 'true' UNION ALL SELECT sch10_ipo_id as info_id , '[공모주납입] '||sch10_item_nm as title , CONCAT('시장구분 : ',f_cdnm('MarketCode', sch10_market_cd, sch10_company_id, f_today()) ,' / ' ,'공모가 : ',COALESCE(TO_CHAR(sch10_price,'FM999,999,999'),'미정') ,E'\n주간사 : ',sch10_note) as content , sch10_pay_date as close_date FROM sch10_ipo WHERE sch10_pay_date BETWEEN #{startDate}::date AND #{endDate}::date AND COALESCE(sch10_cancel_yn,'false') != 'true' UNION ALL SELECT sch10_ipo_id as info_id , '[공모주상장] '||sch10_item_nm as title , CONCAT('시장구분 : ',f_cdnm('MarketCode', sch10_market_cd, sch10_company_id, f_today()) ,' / ' ,'공모가 : ',COALESCE(TO_CHAR(sch10_price,'FM999,999,999'),'미정') ,E'\n주간사 : ',sch10_note) as content , sch10_list_date as close_date FROM sch10_ipo WHERE sch10_list_date BETWEEN #{startDate}::date AND #{endDate}::date AND COALESCE(sch10_cancel_yn,'false') != 'true' ) ipo WHERE #{shareType} IN ('2','%') AND COALESCE(#{classId,jdbcType=BIGINT},0) = 0 AND ( ( #{personId} IN ( SELECT sch02_person_id FROM sch02_share WHERE sch02_info_id = info_id AND sch02_share_cd = '1' ) ) OR ( #{orgId} IN ( SELECT sch02_org_id FROM sch02_share WHERE sch02_info_id = info_id AND sch02_share_cd = '2' ) ) ) AND 'false' = f_get_empTrans(#{personId}, close_date, 'non_stay_yn') ) sch WHERE close_date BETWEEN #{startDate}::date AND #{endDate}::date AND close_date <= COALESCE(f_get_empTrans(manager_id, close_date, 'retire_date')::date,'9999-12-31') AND NOT EXISTS ( SELECT 1 FROM sch04_list WHERE sch04_company_id = company_id AND sch04_info_id = info_id AND sch04_manager_id = manager_id AND sch04_close_date = close_date AND sch04_schedule_cd != '5' ) ) t WHERE 1=1 AND cycle_cd LIKE #{cycleCode} AND CONCAT(title, contt, f_get_empTrans(manager_id, close_date, 'org_code_nm'), f_emp_kor_nm(manager_id)) ILIKE #{searchText}

SELECT sch01_close_date AS close_date , sch01_manage_date AS manage_date , sch01_class_nm AS class_name , sch01_title AS title , sch01_content AS content , sch01_deadline_nm AS deadline_name , sch01_status_nm AS status_name , sch01_person_nm AS person_name , sch01_note AS note , sch01_real_info_id AS real_info_id , ROW_NUMBER() OVER() AS info_id , sch01_class_id AS class_id , sch01_deadline_id AS deadline_id , sch01_manager_id AS manager_id , sch01_manager_nm AS manager_name , sch01_person_id AS person_id , sch01_org_nm AS org_name , sch01_company_id AS company_id FROM ( SELECT sch01_company_id , sch01_title , sch01_content , sch01_manager_id , f_emp_kor_nm(sch01_manager_id) AS sch01_manager_nm , sch01_person_id , CASE WHEN status_cd IN ('1','5','2') THEN f_emp_kor_nm(sch01_person_id) ELSE null END AS sch01_person_nm , org_nm AS sch01_org_nm , sch01_note , sch01_class_id , sch08_class_nm AS sch01_class_nm , close_date AS sch01_close_date , deadline_id AS sch01_deadline_id , deadline_nm AS sch01_deadline_nm , info_id AS sch01_real_info_id , CASE WHEN status_cd IN ('1','5','2') THEN manager_date ELSE null END AS sch01_manage_date , f_cdnm('ScheduleStatusCode', status_cd, sch01_company_id, manager_date) AS sch01_status_nm , seq , ipo_yn FROM ( ---------------------------- -- 스케줄 과거일정 ---------------------------- SELECT sch04_company_id sch01_company_id , sch04_title sch01_title , sch01_content sch01_content , sch04_manager_id sch01_manager_id , sch04_person_id sch01_person_id , sch04_note sch01_note , sch01_class_id sch01_class_id , sch08_class_nm sch08_class_nm , COALESCE(sch08_seq,999) seq , sch04_close_date close_date , sch03_deadline_id deadline_id , f_get_deadline_nm(sch03_deadline_id, '2') deadline_nm , sch03_cycle_cd cycle_cd , sch01_info_id info_id , sch04_mng_org_id org_id , f_org_nm(sch04_mng_org_id, sch04_close_date) org_nm , sch04_manage_date manager_date /* 처리일 */ , COALESCE(sch04_status_cd,'0') status_cd /* 처리상태 */ , 'false' ipo_yn FROM sch04_list INNER JOIN sch03_deadline ON sch03_deadline_id = sch04_deadline_id INNER JOIN sch01_info ON sch01_info_id = sch04_info_id LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id WHERE sch04_company_id = #{companyId} AND sch04_schedule_cd = '1' /*(1:스케줄)*/ AND sch04_close_date BETWEEN #{startDate}::date AND #{endDate}::date AND sch04_status_cd != '9' AND ( ( #{dailyYn} = 'true' AND COALESCE(sch01_daily_yn,'false') = 'true' ) OR ( #{dailyYn} != 'true' ) ) AND COALESCE(sch01_private_yn,'false') != 'true' ---------------------------- -- 스케줄 미래일정 ---------------------------- UNION ALL SELECT * , CAST(f_get_empTrans(sch01_manager_id, close_date, 'org_code_id') AS NUMERIC) org_id , f_get_empTrans(sch01_manager_id, close_date, 'org_code_nm') org_nm , null manager_date /* 처리일 */ , '0' status_cd /* 처리상태 */ , 'false' ipo_yn FROM ( SELECT distinct sch01_company_id , sch01_title , sch01_content , sch01_manager_id , sch01_manager_id as sch01_person_id , sch01_note , sch01_class_id , sch08_class_nm , COALESCE(sch08_seq,999) seq , f_get_std_date(sch03_deadline_id, sys12_day::date, sch01_company_id) close_date , sch03_deadline_id deadline_id , f_get_deadline_nm(sch03_deadline_id, '2') deadline_nm , sch03_cycle_cd cycle_cd , sch01_info_id info_id FROM sch01_info INNER JOIN sch03_deadline ON sch03_info_id = sch01_info_id LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id INNER JOIN sys12_calendar ON ( sys12_company_id = sch01_company_id AND sys12_day BETWEEN #{startDate}::timestamp AND #{endDate}::timestamp ) WHERE sch01_company_id = #{companyId} AND ( ( #{dailyYn} = 'true' AND COALESCE(sch01_daily_yn,'false') = 'true' ) OR ( #{dailyYn} != 'true' ) ) AND COALESCE(sch01_private_yn,'false') != 'true' AND COALESCE(sch01_use_yn,'false') = 'true' AND sch03_cycle_calc_type NOT IN ('02','10') /* (02:수시기간설정/10:즉시)제외 */ AND sch03_cycle_cd NOT IN ('02','03','04','05','06') /* (주/월/분기/반기/연)제외 */ UNION ALL SELECT sch01_company_id , sch01_title , sch01_content , sch01_manager_id , sch01_manager_id as sch01_person_id , sch01_note , sch01_class_id , sch08_class_nm , COALESCE(sch08_seq,999) seq , sch09_day close_date , sch03_deadline_id deadline_id , f_get_deadline_nm(sch03_deadline_id, '2') deadline_nm , sch03_cycle_cd cycle_cd , sch01_info_id info_id FROM sch01_info INNER JOIN sch03_deadline ON sch03_info_id = sch01_info_id INNER JOIN sch09_deadline_day ON sch09_deadline_id = sch03_deadline_id LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id WHERE sch01_company_id = #{companyId} AND ( ( #{dailyYn} = 'true' AND COALESCE(sch01_daily_yn,'false') = 'true' ) OR ( #{dailyYn} != 'true' ) ) AND COALESCE(sch01_private_yn,'false') != 'true' AND COALESCE(sch01_use_yn,'false') = 'true' AND sch03_cycle_calc_type NOT IN ('02','10') /*(02:수시기간설정/10:즉시)제외 */ AND sch03_cycle_cd IN ('02','03','04','05','06') /*(주/월/분기/반기/연) */ AND sch09_day BETWEEN #{startDate}::date AND #{endDate}::date ) tt WHERE close_date BETWEEN #{startDate}::date AND #{endDate}::date AND close_date <= COALESCE(f_get_empTrans(sch01_manager_id, close_date, 'retire_date')::date,'9999-12-31') AND NOT EXISTS ( SELECT 1 FROM sch04_list WHERE sch04_company_id = sch01_company_id AND sch04_info_id = info_id AND sch04_manager_id = sch01_manager_id AND sch04_close_date = close_date ) ---------------------------- -- 공모주 ---------------------------- UNION ALL SELECT #{companyId} , title , content , null manager_id , null person_id , null note , 0 class_id , '공모주' class_nm , 999 seq , close_date , null deadline_id , null deadline_nm , '99' cycle_cd , info_id , sch02_org_id org_id , f_org_nm(sch02_org_id, close_date) org_nm , null manager_date /* 처리일 */ , '0' status_cd /* 처리상태 */ , 'true' ipo_yn FROM () ipo INNER JOIN ( SELECT DISTINCT sch02_info_id , sch02_org_id FROM sch02_share WHERE sch02_company_id = #{companyId} ) share ON sch02_info_id = info_id ) t WHERE 1=1
AND org_id IN ( WITH RECURSIVE org ( org_id, parent_id, depth, path, cycle ) AS ( SELECT org01_code_id as org_id , org02_parent_code_id as parent_id , 0 as depth , ARRAY[org02_kor_nm::text] as path , false as cycle FROM org01_code INNER JOIN org02_info ON ( org02_code_id = org01_code_id AND org02_mod_date = (SELECT MAX(org02_mod_date) FROM org02_info WHERE org02_code_id = org01_code_id AND org02_mod_date <= close_date) ) WHERE org01_company_id = #{companyId} AND org01_code_id = #{orgId} UNION ALL SELECT org01_code_id , org02_parent_code_id , depth + 1 , ARRAY_APPEND(path, org02_kor_nm::text) , org02_kor_nm = ANY(path) FROM org01_code INNER JOIN org02_info ON ( org02_code_id = org01_code_id AND org02_mod_date = (SELECT MAX(org02_mod_date) FROM org02_info WHERE org02_code_id = org01_code_id AND org02_mod_date <= close_date) ) INNER JOIN org ON org_id = org02_parent_code_id WHERE org01_company_id = #{companyId} AND NOT CYCLE ) SELECT org_id FROM org )
AND org_id = #{orgId}
AND cycle_cd LIKE #{cycleCode}
AND CONCAT(sch08_class_nm, sch01_title, sch01_content, org_nm, f_emp_kor_nm(sch01_manager_id)) ILIKE #{searchText} ) sch ORDER BY sch01_close_date, sch01_org_nm COLLATE "ko_KR.utf8", seq, sch01_title COLLATE "ko_KR.utf8"

SELECT * FROM ( SELECT , COALESCE(sch08_class_nm,'') AS class_name, sch08_seq, a.sch01_use_yn AS sort_use_yn FROM sch01_info a LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id WHERE sch01_company_id = #{companyId} AND sch01_manager_id = #{userId}
AND sch01_class_id = #{classId}
AND COALESCE(sch01_use_yn,'false') = 'true'
AND COALESCE(sch01_daily_yn,'false') = 'true'
AND ( SELECT COUNT(*) FROM sch03_deadline WHERE sch03_company_id = sch01_company_id AND sch03_schedule_cd = '1' AND sch03_info_id = sch01_info_id AND sch03_cycle_cd = #{cycleCode} ) != 0
) t WHERE UPPER(CONCAT(title, deadline_name, report)) LIKE UPPER(#{searchText}) ORDER BY COALESCE(sch08_seq,999), sort_use_yn DESC, deadline_name COLLATE "ko_KR.utf8", info_id

SELECT ,
       sch08_class_nm   AS class_name
  FROM sch01_info a
       LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id
 WHERE sch01_info_id = #{infoId}
   AND sch01_company_id = #{companyId}

SELECT sch01_info_id AS info_id, sch01_company_id AS company_id, sch01_title AS title, sch01_content AS content, sch01_report AS report, sch01_manager_id AS manager_id, sch01_note AS note, sch01_use_yn AS use_yn, sch01_dcr_class_tree_id AS dcr_class_tree_id, sch01_private_yn AS private_yn, sch01_daily_yn AS daily_yn, sch01_class_id AS class_id, sch08_class_nm AS class_name FROM sch01_info LEFT OUTER JOIN sch08_class ON sch08_class_id = sch01_class_id WHERE sch01_company_id = #{companyId} AND sch01_manager_id = #{managerId} AND COALESCE(sch01_use_yn ,'false') = 'true' AND COALESCE(sch01_private_yn,'false') != 'true'
AND sch01_class_id = #{classId}
AND UPPER(CONCAT(sch01_title, sch01_report)) LIKE #{searchText} ORDER BY COALESCE(sch08_seq,999), sch01_title COLLATE "ko_KR.utf8"

mapper.update:
UPDATE sch01_info
   SET sch01_class_id   = #{req.classId},
       sch01_title      = #{req.title},
       sch01_content    = #{req.content},
       sch01_daily_yn   = #{req.dailyYn},
       sch01_private_yn = #{req.privateYn},
       sch01_use_yn     = #{req.useYn}
 WHERE sch01_info_id    = #{infoId}
   AND sch01_company_id = #{companyId}

