INSERT INTO sch08_class (sch08_class_id, sch08_person_id, sch08_class_nm, sch08_seq, sch08_use_yn, sch08_note)
SELECT #{newClassId}, #{managerId}, sch08_class_nm, sch08_seq, sch08_use_yn, #{note}
  FROM sch08_class
 WHERE sch08_class_id = #{classId}

INSERT INTO sch01_info (sch01_info_id, sch01_company_id, sch01_title, sch01_content, sch01_report, sch01_manager_id, sch01_note, sch01_use_yn,
                        sch01_dcr_class_tree_id, sch01_private_yn, sch01_daily_yn, sch01_class_id)
SELECT #{newInfoId}, sch01_company_id, sch01_title, sch01_content, sch01_report, #{managerId}, sch01_note, sch01_use_yn,
       sch01_dcr_class_tree_id, sch01_private_yn, sch01_daily_yn, #{newClassId}
